import pandas as pd
import json
import base64
from datetime import datetime

# Read Data
df = pd.read_csv('/app/benchmark/data.csv')

# Process Composers (Split)
all_composers = []
for idx, row in df.iterrows():
    composers = [c.strip() for c in row['Composer'].split(',')]
    for c in composers:
        all_composers.append({'Year': row['Year'], 'Film': row['Film'], 'Composer': c, 'Combined': row['Composer']})

comp_df = pd.DataFrame(all_composers)

# Calculate KPIs
total_ceremonies = len(df)
total_unique_composers = comp_df['Composer'].nunique()
wins = comp_df['Composer'].value_counts()
max_wins = wins.max()

seen = set()
ceremony_repeat = []
for idx, row in df.sort_values('Year').iterrows():
    composers = [c.strip() for c in row['Composer'].split(',')]
    is_repeat = any(c in seen for c in composers)
    ceremony_repeat.append(is_repeat)
    for c in composers:
        seen.add(c)

repeat_rate = (sum(ceremony_repeat) / total_ceremonies) * 100

comp_df['Decade'] = (comp_df['Year'] // 10) * 10
df['Decade'] = (df['Year'] // 10) * 10
unique_by_decade = comp_df.groupby('Decade')['Composer'].nunique()
most_unique_decade = unique_by_decade.idxmax()
most_unique_count = unique_by_decade.max()

# Eras
def get_era(year):
    if year < 1960: return "Golden Age (1934–1959)"
    elif year < 1980: return "Silver Age (1960–1979)"
    elif year < 2000: return "Modern Era (1980–1999)"
    else: return "Contemporary (2000–2026)"

df['Era'] = df['Year'].apply(get_era)
comp_df['Era'] = comp_df['Year'].apply(get_era)

# Prepare Chart.js data
# 1. Top Composers
top_comp = wins.head(10)
top_comp_labels = json.dumps(top_comp.index.tolist())
top_comp_data = json.dumps(top_comp.values.tolist())

# 2. Decade Breakdown (Total Ceremonies vs Unique Winners vs Repeat Ceremonies)
decade_labels = sorted(df['Decade'].unique())
decades_str = json.dumps([f"{d}s" for d in decade_labels])

unique_per_dec = [int(comp_df[comp_df['Decade'] == d]['Composer'].nunique()) for d in decade_labels]
unique_per_dec_str = json.dumps(unique_per_dec)

total_per_dec = [int(len(df[df['Decade'] == d])) for d in decade_labels]
total_per_dec_str = json.dumps(total_per_dec)

# Era stats
era_stats = ""
for era in ["Golden Age (1934–1959)", "Silver Age (1960–1979)", "Modern Era (1980–1999)", "Contemporary (2000–2026)"]:
    era_df = df[df['Era'] == era]
    era_comp = comp_df[comp_df['Era'] == era]
    era_stats += f"<li><strong>{era}</strong>: {len(era_df)} ceremonies, {era_comp['Composer'].nunique()} unique composers. Top winner(s): {', '.join(era_comp['Composer'].value_counts().head(2).index.tolist())}</li>"

